with cleaned as (select *, coalesce(budget, 0) budget_filled, coalesce(dept_name, 'NONE') dept_name_filled from departments where location is not null), metrics as (select *, avg(budget) over w_hist running_avg_budget, max(budget) over w_hist running_max_budget, min(budget) over w_hist running_min_budget, sum(budget) over w_hist running_sum_budget from cleaned where dept_name in ('Marketing', 'HR', 'Finance') window w_hist as (partition by location order by budget, id rows between unbounded preceding and current row)), deduped as (select *, row_number() over (partition by dept_name, location order by running_sum_budget desc, id) as dedup_rank from metrics qualify dedup_rank = 1), eligible as (select s.* from deduped s where not exists (select 1 from employees x where x.dept_id = s.id and month(x.hire_date) in (9, 10, 11))), metrics_departments as (select *, lead(running_min_budget) over (partition by dept_name, location order by running_sum_budget, id) next_running_min_budget, lag(running_min_budget) over (partition by dept_name, location order by running_sum_budget, id) prev_running_min_budget, lag(running_sum_budget) over (partition by dept_name, location order by running_sum_budget, id) prev_running_sum_budget, row_number() over (partition by dept_name, location order by running_sum_budget, id) row_seq from eligible) select id, dept_name, location, dept_name_filled, running_avg_budget, running_min_budget, running_sum_budget, dedup_rank, next_running_min_budget from metrics_departments order by next_running_min_budget nulls first
